begin;
\ir bag-reception-fixture.inc
create extension if not exists pgtap with schema extensions;
select no_plan();
insert into auth.users(id,email,email_confirmed_at) values
 ('f0000000-0000-4000-8000-000000000626','business-owner@example.test',now()),
 ('f0000000-0000-4000-8000-000000000627','business-outsider@example.test',now());
set local role authenticated;
set local "request.jwt.claims"='{"sub":"f0000000-0000-4000-8000-000000000626","role":"authenticated"}';
select set_config('test.tenant',create_tenant('Business seller test','business-seller-test',gen_random_uuid())::text,true);
select set_config('test.profile',jsonb_build_object('name','Synthetic company','email','company@example.test','phone','','addressLine1','','addressLine2','','postalCode','','city','','country','','language','en','notes','','sellerType','business','business',jsonb_build_object('companyName','Synthetic company','vatRegistered',true,'vatNumber','SE123456789001'))::text,true);
select set_config('test.seller',gen_random_uuid()::text,true);
select lives_ok($$select register_seller_with_profile(current_setting('test.tenant')::uuid,current_setting('test.seller')::uuid,current_setting('test.profile')::jsonb)$$,'staff registers business and profile atomically');
select is((select seller_type from sellers where id=current_setting('test.seller')::uuid),'business','type is explicit');
select is((select profile->'business'->>'vatRegistered' from sellers where id=current_setting('test.seller')::uuid),'true','VAT registration remains a boolean');
select is(effective_seller_terms(current_setting('test.tenant')::uuid,current_setting('test.seller')::uuid)->>'commissionBasis','exclusive','business defaults to commission plus VAT');
select lives_ok($$select register_seller_with_profile(current_setting('test.tenant')::uuid,current_setting('test.seller')::uuid,current_setting('test.profile')::jsonb)$$,'same registration safely replays');
select throws_ok($$select register_seller_with_profile(current_setting('test.tenant')::uuid,current_setting('test.seller')::uuid,current_setting('test.profile')::jsonb||'{"sellerType":"private"}')$$,'INVALID_INPUT','private profile cannot carry company details');
select throws_ok($$select save_seller_profile(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.seller')::uuid,1,(current_setting('test.profile')::jsonb-'business')||'{"sellerType":"private"}')$$,'SELLER_TYPE_IMMUTABLE','profile cannot change registered type');
select set_config('test.private',register_seller(current_setting('test.tenant')::uuid,gen_random_uuid(),'Private','','123456')::text,true);
select is((select seller_type from sellers where id=current_setting('test.private')::uuid),'private','legacy registration stays private');
select throws_ok($$select save_seller_profile(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.private')::uuid,0,current_setting('test.profile')::jsonb)$$,'SELLER_TYPE_IMMUTABLE','first edit cannot convert an existing private seller');
select lives_ok($$select register_seller_with_profile(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.profile')::jsonb-'business')$$,'company identifiers are optional');
select throws_ok($$select save_seller_profile(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.seller')::uuid,1,jsonb_set(current_setting('test.profile')::jsonb,'{business,vatRegistered}','"true"'))$$,'INVALID_INPUT','VAT registration requires a boolean');
select set_config('test.edit',gen_random_uuid()::text,true);
select lives_ok($$select save_seller_profile(current_setting('test.tenant')::uuid,current_setting('test.edit')::uuid,current_setting('test.seller')::uuid,1,jsonb_set(current_setting('test.profile')::jsonb,'{business,companyName}','"New company name"'))$$,'business contact changes create a version');
select is((select profile->'business'->>'companyName' from seller_profile_versions where seller_id=current_setting('test.seller')::uuid and revision=1),'Synthetic company','previous business identity remains immutable');
select lives_ok($$select register_seller_with_profile(current_setting('test.tenant')::uuid,current_setting('test.seller')::uuid,current_setting('test.profile')::jsonb)$$,'registration replay works after profile changes');

select publish_store_policy(current_setting('test.tenant')::uuid,gen_random_uuid(),null,(current_store_policy(current_setting('test.tenant')::uuid)->'policy') || '{"commissionRatePercent":48,"minPayoutThreshold":0,"vatModeConsignmentPrivate":"consignment_margin","vatModeConsignmentBusiness":"consignment_business","vatModeStoreOwned":"store_full"}');
select set_config('test.bag',receive_bag(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.seller')::uuid,'')::text,true);
select set_config('test.review',gen_random_uuid()::text,true);
select pg_temp.prepare_bag_reception(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.bag')::uuid,current_setting('test.review')::uuid,0,'Synthetic jacket','Jackets','Good');
select set_config('test.item',gen_random_uuid()::text,true);
select accept_item(current_setting('test.tenant')::uuid,current_setting('test.item')::uuid,'reception_review',current_setting('test.review')::uuid,1,25000);
select set_config('test.sale',gen_random_uuid()::text,true);
select record_sale(current_setting('test.tenant')::uuid,current_setting('test.sale')::uuid,'manual','business-sale','2026-10-24T10:00:00Z','SEK',jsonb_build_array(jsonb_build_object('itemId',current_setting('test.item'),'priceOre',25000)));
select is((select vat_mode from sale_lines where sale_id=current_setting('test.sale')::uuid),'consignment_business','registered business uses full VAT mode');
select is((select vat_basis->>'sellerType' from sale_lines where sale_id=current_setting('test.sale')::uuid),'business','sale freezes explicit type');
select is((select vat_basis->>'sellerVatNumber' from sale_lines where sale_id=current_setting('test.sale')::uuid),'SE123456789001','sale freezes VAT identity');
select is((select commission_vat_ore from sale_lines where sale_id=current_setting('test.sale')::uuid),3000::bigint,'exclusive business commission uses existing VAT arithmetic');

select is((select vat_basis->'supplierVat'->>'grossOre' from sale_lines where sale_id=current_setting('test.sale')::uuid),'10000','approved example credits 100 including supplier VAT');
select is((select vat_basis->'supplierVat'->>'netOre' from sale_lines where sale_id=current_setting('test.sale')::uuid),'8000','supplier net is 80');
select is((select vat_basis->'supplierVat'->>'vatOre' from sale_lines where sale_id=current_setting('test.sale')::uuid),'2000','supplier VAT is 20, not retail VAT 50 or commission VAT 30');

select set_config('test.statement',gen_random_uuid()::text,true);
select lives_ok($$select issue_statement(current_setting('test.tenant')::uuid,current_setting('test.statement')::uuid,current_setting('test.seller')::uuid,'2026-10-24','2026-10-25')$$,'self-billing issued through existing engine');
select is((select self_billing->'lines'->0->>'vatOre' from settlement_statements where id=current_setting('test.statement')::uuid),'2000','invoice freezes supplier VAT');
select is((select self_billing->'supplier'->'business'->>'companyName' from settlement_statements where id=current_setting('test.statement')::uuid),'New company name','invoice freezes business identity');
select is((select number from settlement_statements where id=current_setting('test.statement')::uuid),1,'existing number sequence reused');
select lives_ok($$select issue_statement(current_setting('test.tenant')::uuid,current_setting('test.statement')::uuid,current_setting('test.seller')::uuid,'2026-10-24','2026-10-25')$$,'self-billing safely replays');
select save_seller_profile(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.seller')::uuid,2,jsonb_set(current_setting('test.profile')::jsonb,'{business,vatRegistered}','false'));
select record_return(current_setting('test.tenant')::uuid,gen_random_uuid(),(select id from sale_lines where sale_id=current_setting('test.sale')::uuid),25000,'Return after supplier change','2026-10-25T00:01:00Z');
select set_config('test.to',clock_timestamp()::text,true);
select set_config('test.return_statement',gen_random_uuid()::text,true);
select issue_statement(current_setting('test.tenant')::uuid,current_setting('test.return_statement')::uuid,current_setting('test.seller')::uuid,'2026-10-25',current_setting('test.to')::timestamptz);
select is((select self_billing->'lines'->0->>'vatOre' from settlement_statements where id=current_setting('test.return_statement')::uuid),'-2000','return uses original VAT even after deregistration');
select is((select self_billing->'lines'->0->>'netOre' from settlement_statements where id=current_setting('test.return_statement')::uuid),'-8000','return reverses original net exactly');
select set_config('test.review2',gen_random_uuid()::text,true);
select pg_temp.prepare_bag_reception(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.bag')::uuid,current_setting('test.review2')::uuid,0,'Optional tax jacket','Jackets','Good');
select set_config('test.item2',gen_random_uuid()::text,true);
select accept_item(current_setting('test.tenant')::uuid,current_setting('test.item2')::uuid,'reception_review',current_setting('test.review2')::uuid,1,25000);
select is(simulate_sale(current_setting('test.tenant')::uuid,jsonb_build_array(jsonb_build_object('itemId',current_setting('test.item2'),'priceOre',25000)))->'lines'->0->'vatBasis'->'supplierVat'->>'vatOre','0','non-registered supplier has no separately charged VAT');
select save_seller_profile(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.seller')::uuid,3,current_setting('test.profile')::jsonb);
select is(simulate_sale(current_setting('test.tenant')::uuid,jsonb_build_array(jsonb_build_object('itemId',current_setting('test.item2'),'priceOre',9)))->'lines'->0->'vatBasis'->'supplierVat'->>'vatOre','1','rounding extracts one ore from four ore gross');
select publish_store_policy(current_setting('test.tenant')::uuid,gen_random_uuid(),(current_store_policy(current_setting('test.tenant')::uuid)->>'id')::uuid,(current_store_policy(current_setting('test.tenant')::uuid)->'policy')||'{"vatModeConsignmentBusiness":"consignment_margin","vatRatePercent":20}');
select is(simulate_sale(current_setting('test.tenant')::uuid,jsonb_build_array(jsonb_build_object('itemId',current_setting('test.item2'),'priceOre',25000)))->'lines'->0->'vatBasis'->'supplierVat'->>'rateBp',null,'margin supplier has no separate VAT rate');
select throws_ok($$select issue_statement(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.seller')::uuid,'2026-10-23','2026-10-25',current_setting('test.statement')::uuid)$$,'INVALID_INPUT','credit note cannot misstate the original invoice period');
select save_seller_profile(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.seller')::uuid,4,jsonb_set(current_setting('test.profile')::jsonb,'{name}','"Changed contact"'));
select set_config('test.credit',gen_random_uuid()::text,true);
select issue_statement(current_setting('test.tenant')::uuid,current_setting('test.credit')::uuid,current_setting('test.seller')::uuid,'2026-10-24','2026-10-25',current_setting('test.statement')::uuid);
select is((select self_billing->'lines'->0->>'vatOre' from settlement_statements where id=current_setting('test.credit')::uuid),'-2000','credit note negates original invoice');
select is((select self_billing->'supplier'->'business'->>'companyName' from settlement_statements where id=current_setting('test.credit')::uuid),'New company name','credit note retains original supplier identity');
select is((select seller_contact->>'name' from settlement_statements where id=current_setting('test.credit')::uuid),'Synthetic company','credit contact matches original snapshot');
select is((select self_billing->>'language' from settlement_statements where id=current_setting('test.credit')::uuid),'en','credit document preserves original language');
select is((select self_billing->'lines'->0->>'vatOre' from settlement_statements where id=current_setting('test.statement')::uuid),'2000','original invoice unchanged');
select throws_ok($$update settlement_statements set self_billing=null where id=current_setting('test.statement')::uuid$$,'42501',null,'clients cannot mutate invoice');
reset role;
select throws_ok($$update settlement_statements set self_billing=null where id=current_setting('test.statement')::uuid$$,'55000',null,'invoice snapshot immutable even for privileged updates');
select * from finish();
rollback;
